package dev.hearthside.fabric.client.ui;

import dev.hearthside.core.input.Control;
import dev.hearthside.core.input.ControlLabels;
import dev.hearthside.core.input.PadStyle;
import dev.hearthside.fabric.HearthsideMod;
import java.util.List;
import net.minecraft.resources.Identifier;

/**
 * Hearthside's GUI sprites (Spec A section 4). The art is generated by {@code tools/art/make_sprites.py} into
 * {@code assets/hearthside/textures/gui/sprites/}, so resource packs can restyle it.
 */
public final class HearthSprites {
	/** Cozy hearth: planks behind the lobby and on signs (nine-slice). */
	public static final Identifier WOOD_PANEL = id("hearth/wood_panel");
	/** Cozy hearth: a player card (nine-slice). */
	public static final Identifier PARCHMENT_CARD = id("hearth/parchment_card");
	/** A white pixel frame, tinted with a player's colour (nine-slice). */
	public static final Identifier CARD_FRAME = id("hearth/card_frame");
	public static final Identifier BUTTON = id("hearth/button");
	public static final Identifier BUTTON_HIGHLIGHTED = id("hearth/button_highlighted");
	public static final Identifier BUTTON_DISABLED = id("hearth/button_disabled");
	/** Ember glass: panels over the world (nine-slice). */
	public static final Identifier GLASS_PANEL = id("glass/panel");
	/** Ember glass: the chip behind a button hint (nine-slice). */
	public static final Identifier GLASS_CHIP = id("glass/chip");

	/** Cozy hearth: the lobby's dark plank wall (tiled). */
	public static final Identifier BOARD = id("hearth/board");
	/** Cozy hearth: firelight glowing up from the bottom centre (stretched). */
	public static final Identifier FIRELIGHT = id("hearth/firelight");
	/** An empty seat: a faint glass card (nine-slice). */
	public static final Identifier GHOST_CARD = id("hearth/ghost_card");
	/** A small wooden pill for the title and labels (nine-slice). */
	public static final Identifier PILL = id("hearth/pill");
	/** A white label, tinted with a player's colour (nine-slice). */
	public static final Identifier TAG = id("hearth/tag");
	/** A small controller icon, for counts. */
	public static final Identifier CONTROLLER = id("hearth/controller");
	/** A player's arrow on the party map: outline and rim as drawn, and the inside to tint with their colour. */
	public static final Identifier MAP_ARROW_RIM = id("hearth/map_arrow_rim"), MAP_ARROW_FILL = id("hearth/map_arrow_fill");
	/** The time of day on the party panel. */
	public static final Identifier SUN = id("hearth/sun"), MOON = id("hearth/moon");

	/** Every non-glyph sprite, for checks. */
	public static final List<Identifier> PANELS = List.of(WOOD_PANEL, PARCHMENT_CARD, CARD_FRAME, BUTTON,
			BUTTON_HIGHLIGHTED, BUTTON_DISABLED, GLASS_PANEL, GLASS_CHIP, BOARD, FIRELIGHT, GHOST_CARD, PILL, TAG, CONTROLLER,
			MAP_ARROW_RIM, MAP_ARROW_FILL, SUN, MOON);

	private HearthSprites() {}

	/** The pixel-art icon for a control on this controller family. */
	public static Identifier glyph(Control control, PadStyle style) {
		return id("glyph/" + ControlLabels.glyphId(control, style));
	}

	private static Identifier id(String path) {
		return Identifier.fromNamespaceAndPath(HearthsideMod.MOD_ID, path);
	}
}
